  async function loadBalances(id=warehouseId, page=inventoryPage, search=stockSearch, belowMinimum=belowMinimumOnly) {
    const requestId=++balancesRequestId.current
    if(section!=='inventory-stock'||!id){setBalances([]);setItems([]);setInventoryTotal(0);setBelowMinimumCount(0);setBalancesLoading(false);return}
    setBalancesLoading(true)
    try {
      const params=new URLSearchParams({page:String(page),pageSize:'25',belowMinimumOnly:String(belowMinimum)})
      if(search.trim())params.set('q',search.trim())
      const result=await api<{items:Array<{balance:InventoryBalance;stockItem:StockItem}>;totalCount:number;belowMinimumCount:number}>(`/api/warehouses/${id}/balances/page?${params}`,token)
      if(requestId===balancesRequestId.current){setBalances(result.items.map(row=>row.balance));setItems(result.items.map(row=>row.stockItem));setInventoryTotal(result.totalCount);setBelowMinimumCount(result.belowMinimumCount)}
    } catch(e) { if(requestId===balancesRequestId.current)setError((e as Error).message) } finally { if(requestId===balancesRequestId.current)setBalancesLoading(false) }
  }
