  async function restoreCustomFieldValueRevision(revision:StockCustomFieldValueRevision) {
    if(!customFieldItem||!customFieldValueHistoryDefinition||!window.confirm(`${revision.label} alanının ${new Date(revision.createdAt).toLocaleString('tr-TR')} tarihli değişikliği geri alınsın mı? Önceki değer yeni bir geçmiş kaydı olarak yazılır.`))return
    setCustomFieldBusy(true);setError('')
    try {
      await api<StockCustomFieldValue>(`/api/stock/items/${customFieldItem.id}/custom-fields/${revision.definitionId}/history/${revision.id}/restore`,token,{method:'POST',body:JSON.stringify({confirmation:true})})
      await openCustomFields(customFieldItem);await loadCustomFieldValueHistory(customFieldValueHistoryDefinition);setNotice('Önceki özel alan değeri geri yüklendi; işlem geçmişe eklendi.')
    } catch(e) { setError((e as Error).message) } finally { setCustomFieldBusy(false) }
  }
  async function editCustomField(definition:StockCustomFieldDefinition) {
    const label=window.prompt('Yeni alan etiketi (boş bırakılamaz):',definition.label);if(label===null)return
    let maxLength=definition.maxLength;if(definition.dataType==='Text'){const raw=window.prompt('Yeni en fazla metin uzunluğu (1–500). Mevcut değerler kontrol edilir:',String(definition.maxLength));if(raw===null)return;maxLength=Number(raw)}
    if(definition.dataType==='Text'&&(!Number.isInteger(maxLength)||maxLength<1||maxLength>500)){setError('Metin uzunluğu 1–500 arasında tam sayı olmalıdır.');return}
    const requiredAnswer=window.prompt('Alan zorunlu olsun mu? Evet veya Hayır. Zorunlu yapmak için tüm mevcut stok kartlarında değer bulunmalıdır.',definition.isRequired?'Evet':'Hayır');if(requiredAnswer===null)return
    const answer=requiredAnswer.trim().toLocaleLowerCase('tr-TR');if(!['evet','hayır','hayir'].includes(answer)){setError('Zorunluluk için Evet veya Hayır yazın.');return}
    setCustomFieldBusy(true);setError('')
    try { await api<StockCustomFieldDefinition>(`/api/stock/items/custom-fields/${definition.id}`,token,{method:'PUT',body:JSON.stringify({label,maxLength,isRequired:answer==='evet'})});await openCustomFields(customFieldItem!);await loadCustomFieldHistory(definition);setNotice('Özel alan tanımı yeni sürüm olarak kaydedildi.') }
    catch(e) { setError((e as Error).message) } finally { setCustomFieldBusy(false) }
  }
  async function restoreCustomFieldRevision(revision:StockCustomFieldRevision) {
    if(!customFieldHistoryDefinition||!window.confirm(`${revision.code} alanının v${revision.version} tanımı geri yüklensin mi? Bu işlem yeni bir sürüm oluşturur.`))return
    setCustomFieldBusy(true);setError('')
    try { await api<StockCustomFieldDefinition>(`/api/stock/items/custom-fields/${revision.definitionId}/restore`,token,{method:'POST',body:JSON.stringify({version:revision.version,confirmation:true})});await openCustomFields(customFieldItem!);await loadCustomFieldHistory(customFieldHistoryDefinition);setNotice(`v${revision.version} tanımı yeni sürüm olarak geri yüklendi.`) }
    catch(e) { setError((e as Error).message) } finally { setCustomFieldBusy(false) }
  }
  useEffect(()=>{void loadBase()},[token,section])
  useEffect(()=>{const timer=window.setTimeout(()=>{void loadBalances(warehouseId,inventoryPage,stockSearch,belowMinimumOnly)},stockSearch.trim()?250:0);return()=>window.clearTimeout(timer)},[warehouseId,token,section,inventoryPage,stockSearch,belowMinimumOnly])
